package io.github.diodeme.ji.artifact;

/** Authorized metadata reference; binary bytes remain in the ArtifactStore. */
public record ArtifactReference(
        ArtifactId artifactId,
        ArtifactScope scope,
        String mediaType,
        long size,
        String displayName) {
    public ArtifactReference {
        if (artifactId == null || scope == null) throw new IllegalArgumentException("artifact identity and scope are required");
        if (mediaType == null || mediaType.isBlank()) throw new IllegalArgumentException("mediaType must not be blank");
        if (size < 0) throw new IllegalArgumentException("size must be non-negative");
        if (displayName == null || displayName.isBlank()) throw new IllegalArgumentException("displayName must not be blank");
    }
}
